-- Adds detailed BBGM rating fields to players (no pot column, per user's
-- request -- not needed for this app). Backfills real values for the 100
-- mock players already loaded, pulled from the same league.json.gz export
-- used to build that list. Manually-added players (via the Add Player form)
-- will have these as null, which is fine.
alter table public.players
  add column ovr integer,
  add column tp integer,
  add column ft integer,
  add column fg integer,
  add column ins integer,
  add column dnk integer,
  add column stre integer,
  add column jmp integer,
  add column spd integer,
  add column endu integer,
  add column drb integer,
  add column pss integer,
  add column oiq integer,
  add column diq integer,
  add column reb integer,
  add column hgt integer,
  add column skills text[];

